-- EXP02 CAP-009..017: correct copy in the existing skill catalogue.
-- Registry-active is not runtime readiness. Shared panel status is resolved separately
-- from canonical actor/source evidence; this migration grants or activates nothing.
-- Preserve tenant/custom/reclassified rows and any description edited since the seed.
UPDATE public.paige_skills AS skill
SET description = correction.current_description
FROM (VALUES
  ($copy$ad_spend_efficiency$copy$, $copy$Ad Spend Efficiency Read$copy$, $copy$Reads the available ad-spend and return metrics and interprets return-on-spend, cost-per-lead, and where budget is producing little return — saying so honestly when no ad data is connected.$copy$, $copy$Reviews source-backed ad spend, leads and returns when those measurements are available. Automatic ROAS, cost-per-lead and attribution analysis is not available in Business Review yet; a listed ad provider does not prove a connection or a return.$copy$),
  ($copy$churn_signal_detection$copy$, $copy$Churn Signal Detection$copy$, $copy$Reads the client-activity signals already available and surfaces clients at risk of leaving before they do, naming the specific signal behind each flag.$copy$, $copy$Flags client risk only when permitted activity or service-delivery evidence supports it. Current client and lifecycle totals do not establish churn risk. Source-backed client churn detection is not available in Business Review yet.$copy$),
  ($copy$cohort_analysis$copy$, $copy$Cohort Analysis Read$copy$, $copy$Reads the cohort data already available and describes how retention and expansion differ across acquisition periods.$copy$, $copy$Compares retention and expansion only from authoritative acquisition-cohort evidence. Current client totals cannot reconstruct cohort history. Cohort comparisons are not available in Business Review yet.$copy$),
  ($copy$conversion_funnel_diagnosis$copy$, $copy$Conversion Funnel Diagnosis$copy$, $copy$Reads the funnel-stage data already available and diagnoses where prospects drop off and the most likely reason for the drop.$copy$, $copy$PAIGE can review available opportunity counts and current pipeline evidence. Historical stage-to-stage conversion and drop-off diagnosis are not available in Business Review yet; stage names and current counts do not prove conversion or its cause.$copy$),
  ($copy$engagement_read$copy$, $copy$Engagement Read$copy$, $copy$Reads the engagement metrics already available (email open/click rates, content performance, social/audience growth) and surfaces what's working and what's gone flat.$copy$, $copy$Interprets authorized email, content and audience measurements when their sources provide them. Source-backed channel engagement is not available in Business Review yet. A contact count or listed connection is not evidence of engagement.$copy$),
  ($copy$monthly_qbr_draft$copy$, $copy$Monthly Business Review Draft$copy$, $copy$Drafts a monthly business-review document — what happened, what changed, and the next-30-days focus — from the available metrics, filed as a written deliverable for human approval.$copy$, $copy$PAIGE can explain available business evidence for the last 30 days and identify missing information. Filing a monthly review document for approval and later retrieval remains unverified. A Chat answer is not a filed document or permission to send it.$copy$),
  ($copy$quarterly_narrative$copy$, $copy$Quarterly Narrative Draft$copy$, $copy$Drafts a quarter's story-level narrative synthesis — the arc behind the numbers, not just the numbers — from the available metrics, filed as a written deliverable for human approval.$copy$, $copy$PAIGE can discuss the current quarter using available business evidence and its limitations. Filing a quarterly narrative for approval and later retrieval remains unverified. No unsupported financial history, forecast or delivery is promised.$copy$),
  ($copy$revenue_trend_read$copy$, $copy$Revenue Trend Read$copy$, $copy$Reads the revenue metrics already available (MRR/ARR/cash-flow over the recorded periods) and narrates which direction they're moving and what's driving the change — a historical read, not a forward projection.$copy$, $copy$PAIGE can compare recorded receipts where complete, compatible source periods exist, with currencies kept separate. Recorded receipts are not recognized revenue, MRR, ARR, profit or bank cash. Full revenue-series analysis requires authoritative revenue evidence.$copy$),
  ($copy$weekly_business_review$copy$, $copy$Weekly Business Review$copy$, $copy$Synthesizes the week across the available business metrics into a 5-minute read — what moved and what needs attention — interpreting only what the data supports and persisting nothing.$copy$, $copy$Ask PAIGE for a sourced weekly review of available sales, collections, client, operations and Strategic Play evidence. Missing information stays explicit and recommendations need supporting evidence. This is a read-only review; automatic scheduling, sends and business actions are not included.$copy$)
) AS correction(slug, seeded_name, seeded_description, current_description)
WHERE skill.slug = correction.slug
  AND skill.name = correction.seeded_name
  AND skill.description = correction.seeded_description
  AND skill.category = 'analytics_interpretation'
  AND skill.scoping = 'platform'
  AND skill.created_by = 'system';
